// Prepends a "generated" notice to src/schema.ts (openapi-typescript's own banner is not configurable).
import { readFileSync, writeFileSync } from "node:fs";

const file = new URL("../src/schema.ts", import.meta.url);
const header = `/**
 * GENERATED FILE. DO NOT EDIT.
 * Generated by openapi-typescript from docs/openapi.frozen.json (run scripts/gen-sdk.sh).
 */

`;
const body = readFileSync(file, "utf8").replace(/^\/\*\*[\s\S]*?\*\/\n\n?/, "");
writeFileSync(file, header + body);
